export async function resolveEditorTheme(): Promise<ResolvedEditorTheme | null> {
  try {
    const label = vscode.workspace.getConfiguration('workbench').get<string>('colorTheme');
    if (!label) return null;
    const extensions: ExtensionLike[] = vscode.extensions.all.map((ext) => ({
      extensionPath: ext.extensionPath,
      packageJSON: ext.packageJSON as ExtensionLike['packageJSON'],
    }));
    const found = findThemeDefinition(label, extensions);
    if (!found) return null;
    const raw = await loadRawTheme(found.file);
    const tokenColors = normalizeTokenColors(raw.tokenColors);
    if (!tokenColors) return null;
    return {
      name: `user-theme-${++themeNameCounter}`,
      kind: themeKindFromUiTheme(found.uiTheme),
      tokenColors,
    };
  } catch {
    return null;
  }
}

/**
 * 未支援語言、或高亮引擎尚未就緒時,回傳一整行純文字 token(不上色)——
 * 猜錯顏色比不上色更容易誤導讀者,見 syntax-highlighting spec 的語言判定 requirement。
 */
function plainTextLines(content: string): HighlightToken[][] {
  return content.split('\n').map((line) => [{ content: line }]);
}

export function highlightSnippetLines(content: string, language: string): HighlightToken[][] {
  if (!highlighter || !isLanguageSupported(language)) {
    return plainTextLines(content);
  }
  const { tokens } = highlighter.codeToTokens(content, { lang: language, theme: activeThemeName });
  return tokens.map((line) => line.map(toHighlightToken));
}

